      "text": "Please loop in [REDACTED_PERSON] at [REDACTED_EMAIL] before Friday."
    },
    {
      "message_id": "msg_003",
      "direction": "incoming",
      "text": "[REDACTED_PERSON] says his backup email is [REDACTED_EMAIL] if the main inbox fails."
    }
  ],
  "search_history": [
    {
      "search_id": "search_001",
